WITH metrics_long AS (SELECT * FROM (SELECT id, status, shipping_fee, amount, discount FROM orders) src UNPIVOT (val FOR kpi IN (shipping_fee, amount AS AMOUNT, discount))) SELECT CASE WHEN val >= 89 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, ROUND(AVG(val), 2) AS avg_val, COUNT(*) AS cnt, SUM(CASE WHEN kpi = 'shipping_fee' THEN val ELSE 0 END) AS shipping_fee_val, COUNT(CASE WHEN status = 'PENDING' THEN 1 END) AS pending_count, AVG(val) AS avg_val_2 FROM metrics_long GROUP BY CASE WHEN val >= 89 THEN 'LARGE' ELSE 'SMALL' END ORDER BY shipping_fee_val NULLS LAST
